func TestStringsEscapeWhatSpec43Says(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	var t *strings.Builder = port.NewText()
	model.TextAppendCp(text, 34)
	model.TextAppendCp(text, 92)
	model.TextAppendCp(text, 10)
	model.TextAppendCp(text, 9)
	model.TextAppendCp(text, 13)
	model.TextAppendCp(text, 0)
	model.TextAppendCp(text, 31)
	model.TextAppendCp(text, 8232)
	model.TextAppendCp(text, 8233)
	model.TextAppendCp(text, 47)
	model.TextAppendCp(text, 32)
	json.JsStr(t, text, 0, 11)
	port.AssertText(emonT, t, "\"\\\"\\\\\\n\\t\\u000d\\u0000\\u001f\\u2028\\u2029/ \"", "escapes")
}

